- Rule implementation: src/rules/valid-annotation-format.ts
  - Imports shared options & schema helper: `getResolvedDefaults`, `resolveOptions`, `getRuleSchema`, `getOptionErrors` from `./helpers/valid-annotation-options`.
  - Uses resolved options for validation:
    - Story: `const pathPattern = options.storyPattern; if (pathPattern.test(collapsed)) { return; }` in `validateStoryAnnotation`.
    - Requirement: `const reqPattern = options.reqPattern; if (!reqPattern.test(collapsed)) { context.report({ messageId: "invalidReqFormat", data: { details: buildReqErrorMessage("invalid", collapsed, options) } }); }` in `validateReqAnnotation`.
  - Handles configuration errors via `getOptionErrors()` and a dedicated message:
    ```ts
    messages: { invalidRuleConfiguration: "Invalid configuration for valid-annotation-format: {{details}}", ... },
    ...
    if (optionErrors && optionErrors.length > 0) {
      optionErrors.forEach((details: string) => {
        context.report({ node, messageId: "invalidRuleConfiguration", data: { details } });
      });
    }
    ```
  - References story 010.1 in JSDoc on the rule `create` function and the `Program` handler, with `@req REQ-REGEX-VALIDATION` and `REQ-BACKWARD-COMP`.

- Config & schema helper: src/rules/helpers/valid-annotation-options.ts
  - Defines the configuration interface with both nested and flat fields:
    ```ts
    export interface AnnotationRuleOptions {
      story?: { pattern?: string; example?: string; };
      req?: { pattern?: string; example?: string; };
      storyPathPattern?: string;
      storyPathExample?: string;
      requirementIdPattern?: string;
      requirementIdExample?: string;
    }
    ```
  - Provides resolved runtime options:
    ```ts
    export interface ResolvedAnnotationOptions {
      storyPattern: RegExp;
      storyExample: string;
      reqPattern: RegExp;
      reqExample: string;
    }
    ```
  - Supplies defaults for backward compatibility:
    ```ts
    function getDefaultStoryPattern() { return /^docs\/stories\/[0-9]+\.[0-9]+-DEV-[\w-]+\.story\.md$/; }
    function getDefaultStoryExample() { return "docs/stories/005.0-DEV-EXAMPLE.story.md"; }
    function getDefaultReqPattern() { return /^REQ-[A-Z0-9-]+$/; }
    export function getDefaultReqExample() { return "REQ-EXAMPLE"; }
    ```
  - Validates regex patterns and collects config errors (REQ-REGEX-VALIDATION, REQ-BACKWARD-COMPAT):
    ```ts
    let optionErrors: string[] = [];
    function buildInvalidRegexError(field: string, pattern: string) {
      return `Invalid regular expression for option "${field}": "${pattern}"`;
    }
    function resolvePattern({ nestedPattern, nestedFieldName, flatPattern, flatFieldName, defaultPattern }: ResolvePatternArgs): RegExp {
      const effective = typeof nestedPattern === "string"
        ? { value: nestedPattern, field: nestedFieldName }
        : typeof flatPattern === "string"
          ? { value: flatPattern, field: flatFieldName }
          : null;
      if (!effective) return defaultPattern;
      try { return new RegExp(effective.value); } catch {
        optionErrors.push(buildInvalidRegexError(effective.field, effective.value));
        return defaultPattern;
      }
    }
    ```
  - Resolves nested vs flat options with nested precedence and example override (REQ-PATTERN-CONFIG, REQ-EXAMPLE-MESSAGES, REQ-BACKWARD-COMPAT):
    ```ts
    const nestedStoryPattern = user?.story?.pattern;
    const flatStoryPattern = user?.storyPathPattern;
    const nestedStoryExample = user?.story?.example;
    const flatStoryExample = user?.storyPathExample;
    const nestedReqPattern = user?.req?.pattern;
    const flatReqPattern = user?.requirementIdPattern;
    const nestedReqExample = user?.req?.example;
    const flatReqExample = user?.requirementIdExample;
    ...
    const storyPattern = resolvePattern({ nestedPattern: nestedStoryPattern, nestedFieldName: "story.pattern", flatPattern: flatStoryPattern, flatFieldName: "storyPathPattern", defaultPattern: getDefaultStoryPattern() });
    const reqPattern = resolvePattern({ nestedPattern: nestedReqPattern, nestedFieldName: "req.pattern", flatPattern: flatReqPattern, flatFieldName: "requirementIdPattern", defaultPattern: getDefaultReqPattern() });
    const storyExample = resolveExample(nestedStoryExample, flatStoryExample, getDefaultStoryExample());
    const reqExample = resolveExample(nestedReqExample, flatReqExample, getDefaultReqExample());
    ```
  - Exposes JSON Schema used by the ESLint rule (REQ-SCHEMA-VALIDATION, quality standards):
    ```ts
    export function getRuleSchema() {
      return [
        {
          type: "object",
          properties: {
            story: { type: "object", properties: { pattern: { type: "string" }, example: { type: "string" } }, additionalProperties: false },
            req: { type: "object", properties: { pattern: { type: "string" }, example: { type: "string" } }, additionalProperties: false },
            storyPathPattern: { type: "string" },
            storyPathExample: { type: "string" },
            requirementIdPattern: { type: "string" },
            requirementIdExample: { type: "string" },
          },
          additionalProperties: false,
        },
      ];
    }
    ```
  - File header explicitly ties this helper to story 010.1 and its requirements:
    ```ts
    /**
     * Shared option handling for the valid-annotation-format rule.
     * @story docs/stories/010.1-DEV-CONFIGURABLE-PATTERNS.story.md
     * @req REQ-PATTERN-CONFIG
     * @req REQ-REGEX-VALIDATION
     * @req REQ-BACKWARD-COMPAT
     * @req REQ-EXAMPLE-MESSAGES
     * @req REQ-SCHEMA-VALIDATION
     */
    ```

- Error message helpers: src/rules/helpers/valid-annotation-utils.ts
